solution.solution.py:
from contextlib import contextmanager

_MISSING = object()


@contextmanager
def temporarily(settings, key, value):
    old = settings.get(key, _MISSING)
    settings[key] = value
    try:
        yield
    finally:
        if old is _MISSING:
            del settings[key]
        else:
            settings[key] = old

unitTests:
@test("changes inside, restores after")
def _():
    s = {"volume": 5}
    with temporarily(s, "volume", 0):
        check_eq(s["volume"], 0)
    check_eq(s, {"volume": 5})

@test("restores after an exception")
def _():
    s = {"volume": 5}
    def body():
        with temporarily(s, "volume", 9):
            raise RuntimeError("boom")
    check_raises(RuntimeError, body)
    check_eq(s, {"volume": 5})

@test("a new key is removed again")
def _():
    s = {}
    with temporarily(s, "debug", True):
        check_eq(s, {"debug": True})
    check_eq(s, {})

@test("a stored None is restored")
def _():
    s = {"name": None}
    with temporarily(s, "name", "x"):
        pass
    check_eq(s, {"name": None})

